const APPLY_BLOCK="const COMPANY_OS_DASHBOARD_HELPER='/opt/prhm-agent-selfmaint-exec/actions/company-os-dashboard-v1.js';\nconst COMPANY_OS_DASHBOARD_RESULT='/var/lib/prhm-agent-selfmaint-exec/company-os-dashboard-v1/latest.json';\nfunction applyCompanyOsDashboardV1(){\n  if(!fs.existsSync(COMPANY_OS_DASHBOARD_HELPER))throw new Error('company_os_dashboard_helper_missing');\n  try{if(fs.existsSync(COMPANY_OS_DASHBOARD_RESULT))fs.unlinkSync(COMPANY_OS_DASHBOARD_RESULT)}catch{}\n  const unit='prhm-company-os-dashboard-install-v1-'+Date.now();\n  const args=['--wait','--unit='+unit,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=PrivateDevices=true','--property=ProtectSystem=full','--property=ProtectHome=read-only','--property=ProtectKernelTunables=true','--property=ProtectKernelModules=true','--property=ProtectControlGroups=true','--property=RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6','--property=ReadWritePaths=/opt/prhm-company-os-dashboard /etc/prhm-company-os-dashboard /var/lib/prhm-company-os-dashboard /var/lib/prhm-agent-selfmaint-exec/company-os-dashboard-v1 /etc/systemd/system /etc/httpd/conf.d /root /var/backups','--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',COMPANY_OS_DASHBOARD_HELPER];\n  cp.execFileSync('/usr/bin/systemd-run',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:300000});\n  if(!fs.existsSync(COMPANY_OS_DASHBOARD_RESULT))throw new Error('company_os_dashboard_result_missing');\n  const result=readJson(COMPANY_OS_DASHBOARD_RESULT);\n  if(result.ok!==true||result.action!=='company_os_dashboard_v1'||result.schema_version!=='prhm.host-action-result.v1'||result.installed!==true||result.dashboard_health!==true||result.snapshot_schema!=='prhm.company-os-dashboard.snapshot.v1'||result.proxy_http_verified!==true||result.auth_required!==true||result.read_only!==true||result.database_mutation!==false||result.business_mutation!==false||result.p0_live!==false||result.proposal_send!==false||result.bid_send!==false)throw new Error('company_os_dashboard_result_invalid');\n  return result;\n}\n";
function fail(m){throw new Error(m)}function shaBuf(b){return crypto.createHash('sha256').update(b).digest('hex')}function sha(f){return shaBuf(fs.readFileSync(f))}
function replaceOnce(s,a,b,l){const i=s.indexOf(a);if(i<0)fail('anchor_missing:'+l);if(s.indexOf(a,i+1)>=0)fail('anchor_not_unique:'+l);return s.slice(0,i)+b+s.slice(i+a.length)}
function exec(f,args,opt={}){const r=cp.spawnSync(f,args,{encoding:'utf8',maxBuffer:4*1024*1024,...opt});if(r.error)fail('exec_error:'+f+':'+r.error.message);if(r.status!==0)fail('exec_failed:'+f+':'+r.status+':'+String(r.stderr||'').slice(-1600));return r}
function baseline(){for(const [f,x] of Object.entries(EXPECTED)){if(!fs.existsSync(f))fail('missing:'+f);const a=sha(f);if(a!==x)fail('sha_mismatch:'+f+':'+a+':'+x)}if(fs.existsSync(FILES.helper))fail('dashboard_helper_already_exists')}
function patchBase(s){return replaceOnce(s,BASE_OLD,BASE_NEW,'base_spec')}
function patchExecutor(s){s=replaceOnce(s,EXEC_SPEC_OLD,EXEC_SPEC_NEW,'executor_spec');s=replaceOnce(s,'function verifyProcessSandboxV2(){',APPLY_BLOCK+'function verifyProcessSandboxV2(){','executor_apply_block');s=replaceOnce(s,DISPATCH_OLD,DISPATCH_NEW,'executor_dispatch');s=replaceOnce(s,VERSION_OLD,VERSION_NEW,'executor_version');return s}
function patchPlugin(s){return replaceOnce(s,PLUGIN_OLD,PLUGIN_NEW,'plugin_enum')}
function patchPolicy(s){const p=JSON.parse(s);if(p.operations?.['host_action.company_os_dashboard_v1'])fail('policy_operation_already_present');p.operations['host_action.company_os_dashboard_v1']={level:4};if(!Array.isArray(p.typed_scopes))fail('policy_typed_scopes_missing');if(p.typed_scopes.some(x=>x&&x.action===ACTION))fail('policy_scope_already_present');p.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:'host_action.company_os_dashboard_v1',principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});p.version='2026-08-15.4-company-os-dashboard-v1';return JSON.stringify(p,null,2)+'\n'}
function patchV4Helper(s,newPluginSha){return replaceOnce(s,EXPECTED[FILES.plugin],newPluginSha,'v4_plugin_sha')}
function syntax(name,content,esm=false){const tmp='/tmp/prhm-v9-'+name+'-'+process.pid+(esm?'.mjs':'.js');try{fs.writeFileSync(tmp,content,{mode:0o600});exec('/usr/local/bin/prhm-node',['--check',tmp])}finally{try{fs.unlinkSync(tmp)}catch{}}}
function unixHealth(sock,version){for(let i=0;i<50;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','--unix-socket',sock,'http://localhost/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true&&(!version||x.version===version))return x}catch{}}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}fail('unix_health_not_ready:'+sock)}
function loopHealth(port){for(let i=0;i<50;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','http://127.0.0.1:'+port+'/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true)return x}catch{}}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}fail('loop_health_not_ready:'+port)}
function atomic(file,data,mode){const tmp=file+'.v9-'+process.pid+'.tmp';fs.writeFileSync(tmp,data,{mode});fs.chmodSync(tmp,mode);fs.renameSync(tmp,file)}
function candidate(){const o={base:fs.readFileSync(FILES.base,'utf8'),executor:fs.readFileSync(FILES.executor,'utf8'),plugin:fs.readFileSync(FILES.plugin,'utf8'),policy:fs.readFileSync(FILES.policy,'utf8'),v4helper:fs.readFileSync(FILES.v4helper,'utf8')};const c={base:patchBase(o.base),executor:patchExecutor(o.executor),plugin:patchPlugin(o.plugin),policy:patchPolicy(o.policy),v4helper:null,helper:Buffer.from(HELPER_B64,'base64')};const pluginSha=shaBuf(Buffer.from(c.plugin));c.v4helper=patchV4Helper(o.v4helper,pluginSha);return {o,c,pluginSha}}
function validate(c){syntax('base',c.base);syntax('executor',c.executor);syntax('plugin',c.plugin,true);JSON.parse(c.policy);syntax('v4helper',c.v4helper);syntax('helper',c.helper.toString('utf8'));if(shaBuf(c.helper)!==HELPER_SHA)fail('helper_sha_mismatch')}
function helperPreflight(c){const tmp='/tmp/prhm-v9-dashboard-helper-'+process.pid+'.js';try{fs.writeFileSync(tmp,c.helper,{mode:0o700});const r=exec('/usr/local/bin/prhm-node',[tmp,'--preflight-only'],{timeout:90000});const x=JSON.parse(String(r.stdout||'').trim());if(x.ok!==true||x.preflight_only!==true||x.action!==ACTION||x.production_mutation!==false||x.p0_live!==false||x.proposal_send!==false||x.bid_send!==false)fail('dashboard_helper_preflight_invalid');return x}finally{try{fs.unlinkSync(tmp)}catch{}}}
function restart(){exec('/usr/bin/systemctl',['restart','prhm-agent-selfmaint.service']);exec('/usr/bin/systemctl',['restart','prhm-agent-selfmaint-exec.service']);exec('/usr/bin/systemctl',['restart','prhm-agent-mcp.service']);return {base:unixHealth('/run/prhm-agent-selfmaint/selfmaint.sock'),self:unixHealth('/run/prhm-agent-selfmaint-exec/exec.sock',VERSION),mcp:loopHealth(8123)}}
function main(){const args=process.argv.slice(2);if(args.length>1||(args.length===1&&args[0]!=='--preflight-only'))fail('unexpected_arguments');if(process.getuid&&process.getuid()!==0)fail('must_run_as_root');baseline();const {o,c,pluginSha}=candidate();validate(c);const hp=helperPreflight(c);const report={ok:true,schema_version:'prhm.host-action-bootstrap-preflight.v1',preflight_only:args[0]==='--preflight-only',action:ACTION,current_hashes:EXPECTED,candidate_hashes:{base:shaBuf(Buffer.from(c.base)),executor:shaBuf(Buffer.from(c.executor)),plugin:pluginSha,policy:shaBuf(Buffer.from(c.policy)),v4helper:shaBuf(Buffer.from(c.v4helper)),helper:HELPER_SHA},target_version:VERSION,helper_preflight:hp,dashboard_installed:false,database_mutation:false,business_mutation:false,p0_live:false,proposal_send:false,bid_send:false,production_mutation:false};if(args[0]==='--preflight-only'){process.stdout.write(JSON.stringify(report)+'\n');return}const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14),backup='/var/backups/prhm-host-actions-v9-company-os-dashboard-'+stamp;fs.mkdirSync(backup,{recursive:true,mode:0o700});const modes={base:0o755,executor:0o755,plugin:0o644,policy:0o644,v4helper:0o755};for(const k of ['base','executor','plugin','policy','v4helper']){const dst=path.join(backup,k+'-'+path.basename(FILES[k])+'.bak');fs.copyFileSync(FILES[k],dst,fs.constants.COPYFILE_EXCL);fs.chmodSync(dst,0o600)}let ok=false;try{atomic(FILES.helper,c.helper,0o755);for(const k of ['base','executor','plugin','policy','v4helper'])atomic(FILES[k],c[k],modes[k]);for(const k of ['base','executor','plugin','policy','v4helper'])if(sha(FILES[k])!==report.candidate_hashes[k])fail('post_sha_mismatch:'+k);if(sha(FILES.helper)!==HELPER_SHA)fail('helper_post_sha_mismatch');const health=restart();const p=JSON.parse(fs.readFileSync(FILES.policy,'utf8'));if(p.operations?.['host_action.company_os_dashboard_v1']?.level!==4)fail('policy_operation_postverify_failed');if(!p.typed_scopes.some(x=>x&&x.action===ACTION&&x.operation==='host_action.company_os_dashboard_v1'&&x.risk==='critical'))fail('policy_scope_postverify_failed');if(!fs.readFileSync(FILES.plugin,'utf8').includes('company_os_dashboard_v1'))fail('plugin_enum_postverify_failed');if(!fs.readFileSync(FILES.v4helper,'utf8').includes(pluginSha))fail('v4_plugin_sha_postverify_failed');ok=true;process.stdout.write(JSON.stringify({ok:true,schema_version:'prhm.host-action-install-result.v1',installed:true,version:VERSION,action:ACTION,helper_sha256:HELPER_SHA,mcp_plugin_sha256:pluginSha,approval_policy_version:p.version,health,dashboard_installed:false,database_mutation:false,business_mutation:false,p0_live:false,proposal_send:false,bid_send:false,backup_dir:backup})+'\n')}finally{if(!ok){try{for(const k of ['base','executor','plugin','policy','v4helper']){const src=path.join(backup,k+'-'+path.basename(FILES[k])+'.bak');if(fs.existsSync(src))atomic(FILES[k],fs.readFileSync(src),modes[k])}try{fs.unlinkSync(FILES.helper)}catch(e){if(e.code!=='ENOENT')throw e}restart()}catch(rb){process.stderr.write('rollback_failed:'+String(rb&&rb.stack||rb)+'\n')}}}}
try{main()}catch(e){process.stderr.write(String(e&&e.stack||e)+'\n');process.exit(1)}
